HWND AlwaysOnTop::ResolveTransparencyTargetWindow(HWND window)
{
    if (!window || !IsWindow(window) || !IsPinned(window))
    {
        return nullptr;
    }

    if (IsUnsupportedShellTarget(window))
    {
        CleanupInvalidTrackedWindow(window);
        return nullptr;
    }

    return window;
}

